	private void stableIndexKeepsRows(String plainQuery, boolean nativeEnabled) {
		String orderedQuery = plainQuery + " ORDER BY STABLE_INDEX(?a)";
		Repository memory = memory();
		Repository lmdb = lmdb("shape_" + nativeEnabled + "_" + Math.abs(plainQuery.hashCode()), nativeEnabled);
		try {
			Map<String, Integer> expected = run(memory, plainQuery, null);
			Map<String, Integer> actual = run(lmdb, orderedQuery, null);
			assertThat(expected).isNotEmpty();
			assertThat(actual).isEqualTo(expected);
		} finally {
			memory.shutDown();
			lmdb.shutDown();
		}
	}

