	@Test
	void swapRefusedWhenMovedArgumentBindDependsOnOtherSide() {
		StatementPattern q = pattern("b", "urn:q", "c");
		Extension extension = new Extension(pattern("a", "urn:p", "b"));
		extension.addElement(new ExtensionElem(new Var("c"), "d"));
		Join join = new Join(q, extension);

		LmdbStableOrderPlanner planner = new LmdbStableOrderPlanner(orderedSource());
		assertThat(planner.isBlockedByPushedFilter(join, "a")).isTrue();
		assertThat(planner.plan(join, "a")).isEmpty();
	}

